def manhattan_distance(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def solve(input_str):
    def can_reach(index, curr_index, target):
        queue = [(curr_index, 0)]
        visited = set()
        while queue:
            node, steps = queue.pop(0)
            if node == index:
                return steps
            if node not in visited:
                visited.add(node)
                if node < target:
                    queue.append((node + 1, steps + 1))
                if node > 0:
                    queue.append((node - 1, steps + 1))
                for i in range(max(0, node - 2), min(len(input_str) - 1, node + 3)):
                    queue.append((i, steps + 1 + manhattan_distance([node, i], [index, target])))
        return float('inf')

    arr = [int(digit) for digit in input_str]
    target = arr[0]
    max_dist = float('inf')
    for i in range(4):
        dist = can_reach(i, 0, target)
        max_dist = min(max_dist, dist)
        target = arr[i]
    return max_dist

