                elif not skills[2] or not skills[3]:
                    break
                else:
                    heappush(total, (skills[3].pop(0), 3))
                    res += val
            else:
                heappush(total, (skills[1].pop(0), 1))
                heappush(total, (skills[2].pop(0), 2))
