def solve(n, m, actions):
    stack = deque([i for i in range(1, n+1)])
    actions = [0] + [0] + actions
    res = [0] * n
    for i in range(1, m+1):
        if stack[0]!= actions[i]:
            stack.popleft()
            stack.append(actions[i])
        if stack[0] == i:
            for j in range(n):
                if stack[j+1] == i:
                    res[j] = i
                    stack.remove(i)
                    stack.appendleft(i)
    return res

